function(container, apiUrl, tables) {
  let selectedWorkRecord = null;
  let selectedSuspendRecord = null;

  // 中断中作業の再描画
  function renderSuspendedWorks(workRecords, suspendRecords) {
    const tbody = container.querySelector("#suspended-work-tbody");

    // 中断中の作業記録を抽出（進捗状況が「中断」で、対応する中断記録の終了日時がnull）
    const suspendedWorks = workRecords.filter(work => 
      work.進捗状況 === "中断" && 
      suspendRecords.some(suspend => 
        suspend.作業記録ID === work.作業記録ID && !suspend.中断終了日時
      )
    );

    tbody.innerHTML = suspendedWorks.map(work => {
      const suspendRecord = suspendRecords.find(s => 
        s.作業記録ID === work.作業記録ID && !s.中断終了日時
      );

      const suspendStart = suspendRecord ? new Date(suspendRecord.中断開始日時).toLocaleString() : "";
      const suspendReason = suspendRecord ? suspendRecord.中断理由区分 : "";
      const suspendDuration = suspendRecord && suspendRecord.中断時間 ? `${suspendRecord.中断時間}分` : "計算中";

      return `
        <tr data-work-id="${work.作業記録ID}" data-suspend-id="${suspendRecord?.中断記録ID || ''}">
          <td>${work.作業内容 || ""}</td>
          <td>${work.プロジェクト名 || ""}</td>
          <td>${suspendStart}</td>
          <td>${suspendReason}</td>
          <td>${suspendDuration}</td>
          <td>
            <button class="action-btn resume-btn" data-work-id="${work.作業記録ID}" data-suspend-id="${suspendRecord?.中断記録ID || ''}">再開</button>
          </td>
        </tr>
      `;
    }).join("");
  }

  // 初期データ読み込み
  async function loadData() {
    try {
      const workRecords = await window.aivicApi.list(1); // 作業記録
      const suspendRecords = await window.aivicApi.list(2); // 中断記録

      if (workRecords && suspendRecords) {
        renderSuspendedWorks(workRecords, suspendRecords);
      }
    } catch (error) {
      console.error("データ読み込みエラー:", error);
    }
  }

  // 現在時刻を再開時刻にセット
  function setCurrentTime() {
    const now = new Date();
    const localDateTime = new Date(now.getTime() - now.getTimezoneOffset() * 60000).toISOString().slice(0, 16);
    container.querySelector("#resume-time").value = localDateTime;
  }

  // 作業再開フォーム表示
  function showResumeForm(workRecord, suspendRecord) {
    selectedWorkRecord = workRecord;
    selectedSuspendRecord = suspendRecord;

    container.querySelector("#selected-work-name").textContent = workRecord.作業内容 || "";
    container.querySelector("#suspend-start-time").textContent = suspendRecord ? new Date(suspendRecord.中断開始日時).toLocaleString() : "";
    container.querySelector("#suspend-reason").textContent = suspendRecord ? suspendRecord.中断理由区分 : "";

    setCurrentTime();

    container.querySelector("#resume-form").classList.remove("hidden");
  }

  // 作業再開フォーム非表示
  function hideResumeForm() {
    selectedWorkRecord = null;
    selectedSuspendRecord = null;
    container.querySelector("#resume-form").classList.add("hidden");

    // フォームリセット
    container.querySelector("#resume-time").value = "";
    container.querySelector("#resume-reason-category").value = "";
    container.querySelector("#resume-reason-detail").value = "";
  }

  // 確認ダイアログ表示
  function showConfirmDialog() {
    const workName = selectedWorkRecord?.作業内容 || "";
    const resumeTime = container.querySelector("#resume-time").value;
    const reasonCategory = container.querySelector("#resume-reason-category").value;
    const reasonDetail = container.querySelector("#resume-reason-detail").value;

    const content = `
      <div><strong>作業項目:</strong> ${workName}</div>
      <div><strong>再開時刻:</strong> ${new Date(resumeTime).toLocaleString()}</div>
      <div><strong>再開理由:</strong> ${reasonCategory}</div>
      ${reasonDetail ? `<div><strong>詳細:</strong> ${reasonDetail}</div>` : ""}
      <br>
      <div>この内容で作業を再開しますか？</div>
    `;

    container.querySelector("#confirm-content").innerHTML = content;
    container.querySelector("#confirm-dialog").classList.remove("hidden");
  }

  // 確認ダイアログ非表示
  function hideConfirmDialog() {
    container.querySelector("#confirm-dialog").classList.add("hidden");
  }

  // 作業再開処理
  async function resumeWork() {
    try {
      const resumeTime = container.querySelector("#resume-time").value;
      const reasonCategory = container.querySelector("#resume-reason-category").value;
      const reasonDetail = container.querySelector("#resume-reason-detail").value;

      if (!resumeTime || !reasonCategory) {
        alert("再開時刻と再開理由区分は必須です。");
        return;
      }

      // 中断記録を更新（終了時刻を設定）
      if (selectedSuspendRecord) {
        const suspendStartTime = new Date(selectedSuspendRecord.中断開始日時);
        const resumeDateTime = new Date(resumeTime);
        const suspendDuration = Math.floor((resumeDateTime - suspendStartTime) / (1000 * 60)); // 分単位

        await window.aivicApi.update(2, selectedSuspendRecord.中断記録ID, {
          中断終了日時: resumeTime,
          中断時間: suspendDuration,
          対応状況: "解決済み"
        });
      }

      // 作業記録を更新（進捗状況を「作業中」に変更）
      await window.aivicApi.update(1, selectedWorkRecord.作業記録ID, {
        進捗状況: "作業中"
      });

      hideConfirmDialog();
      hideResumeForm();

      // 画面遷移
      window.showScreen("scr-1778907296658"); // 工数入力画面

    } catch (error) {
      console.error("作業再開エラー:", error);
      alert("作業再開に失敗しました。");
    }
  }

  // イベントリスナー
  container.addEventListener("click", async (e) => {
    // 再開ボタン
    const resumeBtn = e.target.closest(".resume-btn");
    if (resumeBtn) {
      const workId = resumeBtn.dataset.workId;
      const suspendId = resumeBtn.dataset.suspendId;

      try {
        const workRecords = await window.aivicApi.list(1);
        const suspendRecords = await window.aivicApi.list(2);

        const workRecord = workRecords?.find(w => w.作業記録ID === workId);
        const suspendRecord = suspendRecords?.find(s => s.中断記録ID === suspendId);

        if (workRecord) {
          showResumeForm(workRecord, suspendRecord);
        }
      } catch (error) {
        console.error("データ取得エラー:", error);
      }
      return;
    }

    // キャンセルボタン
    if (e.target.id === "btn-cancel") {
      hideResumeForm();
      return;
    }

    // 作業再開ボタン
    if (e.target.id === "btn-resume") {
      showConfirmDialog();
      return;
    }

    // 確認ダイアログのキャンセル
    if (e.target.id === "btn-confirm-cancel") {
      hideConfirmDialog();
      return;
    }

    // 確認ダイアログのOK
    if (e.target.id === "btn-confirm-ok") {
      await resumeWork();
      return;
    }

    // 戻るボタン
    if (e.target.id === "btn-back") {
      window.history.back();
      return;
    }
  });

  // 初期データ読み込み
  loadData();
}
